/* Stagify.ai — the homepage hero's room/style picker.
 *
 * The hero headline is a sentence with two holes in it: "Stage this <room> in <style>".
 * Both are dropdowns, and picking either swaps the photo beside them. Every combination is
 * a real render of ONE source photo (media-webp/example/Original.webp) produced by the same
 * pipeline a visitor's own upload goes through, so the hero demonstrates the product rather
 * than describing it. The grid is generated by
 * to-build/media-png/example/tools/generate-combos.mjs; read that folder's README before
 * adding a room type, because two of them cannot work here (see ROOMS below).
 *
 * THIS FILE HAS NO IMPORTS, ON PURPOSE. It is the first module tag in index.html so it runs
 * as soon as the document is parsed. Give it an import and it joins app.js's 18-deep graph
 * and stops running early, which is the whole reason carousel.js (which this replaces) was
 * moved to the top of <head> in the first place.
 *
 * IT ADOPTS, IT DOES NOT BUILD. The <img> in `.hp-stage` is the page's LCP element and
 * ships in public/index.html so the preload scanner finds it in the first packet. This file
 * binds to that node and never replaces it — replacing it, even with an identical src,
 * restarts the LCP candidate at the later time. Same rule that governed carousel.js.
 * test/frontend/hero-picker-lcp.test.js pins the three-way agreement between the <img>, the
 * <link rel="preload"> and the default selection below.
 *
 * WITH JAVASCRIPT OFF the hero still reads correctly and still shows a staged room: the
 * markup ships the default sentence and the default photo. All that is lost is the ability
 * to change them.
 *
 * IT REMEMBERS THE VISITOR'S PICK across visits (see STORE_KEY below). That is a real cost
 * to the LCP work above and it is worth being honest about it: a returning visitor whose
 * pick is not the default pays for two images on the first paint, and their LCP is the
 * second one. The markup cannot ship their pick instead, because index.html is one static
 * file served to everyone and cached as such.
 */

/* Room types, in menu order. The keys are the ones lib/staging/promptMatrix.js uses, and
 * `slug` is the filename half in media-webp/example/<style>-<room>.webp.
 *
 * `Outdoors` and `Dorm` are deliberately absent. Outdoors belongs to Exterior Studio and
 * reads as broken in the sentence ("Stage this Outdoors in Modern"); Dorm was excluded by
 * product decision. Both still exist in promptMatrix.js and are untouched by their absence.
 *
 * A NOTE BEFORE YOU ADD ONE. The source photo is a corner living room with floor-to-ceiling
 * glass, a structural column and a herringbone floor, and the picker swaps rooms inside a
 * fixed frame, so the visitor is comparing architecture directly. Bedroom, living room,
 * dining room and office keep all of it. Kitchen and Bathroom cannot: a kitchen needs
 * cabinetry and a bathroom needs plumbing, so the model builds walls that are not in the
 * source and the column disappears. They are listed here because they were asked for; if the
 * "same room" reading ever matters more than the coverage, they are the two to cut.
 */
const ROOMS = [
  { key: 'bedroom', slug: 'bedroom', label: 'hero.rooms.bedroom', menu: 'roomTypes.bedroom' },
  { key: 'livingRoom', slug: 'living-room', label: 'hero.rooms.livingRoom', menu: 'roomTypes.livingRoom' },
  { key: 'diningRoom', slug: 'dining-room', label: 'hero.rooms.diningRoom', menu: 'roomTypes.diningRoom' },
  { key: 'kitchen', slug: 'kitchen', label: 'hero.rooms.kitchen', menu: 'roomTypes.kitchen' },
  { key: 'office', slug: 'office', label: 'hero.rooms.office', menu: 'roomTypes.office' },
  { key: 'bathroom', slug: 'bathroom', label: 'hero.rooms.bathroom', menu: 'roomTypes.bathroom' },
];

/* Furniture styles, in menu order. `standard` and `custom` exist in promptMatrix.js but are
 * not user-facing choices, so they are not offered here. Labels come from the shared
 * furnitureStyles pack the studios already use, so a style renamed there is renamed here. */
const STYLES = [
  { key: 'modern', slug: 'modern', label: 'furnitureStyles.modern' },
  { key: 'scandinavian', slug: 'scandinavian', label: 'furnitureStyles.scandinavian' },
  { key: 'coastal', slug: 'coastal', label: 'furnitureStyles.coastal' },
  { key: 'farmhouse', slug: 'farmhouse', label: 'furnitureStyles.farmhouse' },
  { key: 'luxury', slug: 'luxury', label: 'furnitureStyles.luxury' },
  { key: 'midcentury', slug: 'midcentury', label: 'furnitureStyles.midcentury' },
];

/* The pair the markup ships painted. Changing either half here means changing the static
 * <img> in index.html and the <head> preload with it, or the first paint shows one room and
 * the script immediately swaps it for another. The test named above fails if you don't. */
const DEFAULT_ROOM = 'bedroom';
const DEFAULT_STYLE = 'modern';

const DIR = 'media-webp/example/';
const ORIGINAL = DIR + 'Original.webp';

/** English fallbacks, used before the language pack resolves and if a key ever goes missing. */
const FALLBACK = {
  'hero.rooms.bedroom': 'bedroom',
  'hero.rooms.livingRoom': 'living room',
  'hero.rooms.diningRoom': 'dining room',
  'hero.rooms.kitchen': 'kitchen',
  'hero.rooms.office': 'office',
  'hero.rooms.bathroom': 'bathroom',
  'roomTypes.bedroom': 'Bedroom',
  'roomTypes.livingRoom': 'Living room',
  'roomTypes.diningRoom': 'Dining room',
  'roomTypes.kitchen': 'Kitchen',
  'roomTypes.office': 'Office',
  'roomTypes.bathroom': 'Bathroom',
  'furnitureStyles.modern': 'Modern',
  'furnitureStyles.scandinavian': 'Scandinavian',
  'furnitureStyles.coastal': 'Coastal',
  'furnitureStyles.farmhouse': 'Farmhouse',
  'furnitureStyles.luxury': 'Luxury',
  'furnitureStyles.midcentury': 'Midcentury',
  'hero.seeOriginal': 'See original',
  'hero.seeStaged': 'See staged',
  'hero.stageAlt': '{style} {room}, virtually staged',
  'hero.originalAlt': 'The same room before staging, empty',
};

/**
 * A language-pack string, or its English fallback.
 * @param {string} key
 * @returns {string}
 */
function t(key) {
  const ls = /** @type {any} */ (window).LanguageSystem;
  const value = ls && typeof ls.getText === 'function' ? ls.getText(key) : null;
  return value || FALLBACK[key] || key;
}

const byKey = (list, key) => list.find((x) => x.key === key) || list[0];

/* ------------------------------------------------------------------- remembering */

/* Where the last pick is kept. localStorage rather than a cookie because nothing here needs
 * to reach the server, and a cookie would vary a page that is otherwise identical for every
 * visitor. Only the two selections are stored; "See original" is a way of looking at the
 * current pick, not part of it, so it always starts off. */
const STORE_KEY = 'heroPick';

/**
 * The remembered pair, or null if there isn't one.
 *
 * Validated against the CURRENT lists rather than trusted. `byKey` is not used for this on
 * purpose: it falls back to the first entry, which would quietly turn a dropped room type
 * into "bedroom" and a dropped style into "modern" while still reporting a hit. Here an
 * unrecognised half has to mean "no stored pick", or a rename ships a hero that opens on an
 * image that was never generated — empty, for exactly the returning visitors this is for.
 *
 * @returns {{room: object, style: object}|null}
 */
function readStored() {
  let raw = null;
  try {
    raw = window.localStorage.getItem(STORE_KEY);
  } catch {
    return null; // storage blocked or disabled; the default pair is a perfectly good answer
  }
  const [styleKey, roomKey] = String(raw || '').split('|');
  const style = STYLES.find((s) => s.key === styleKey);
  const room = ROOMS.find((r) => r.key === roomKey);
  return style && room ? { room, style } : null;
}

/**
 * Write the pick down. Failure is ignored: Safari's private mode throws on setItem and a
 * full quota throws everywhere, and neither is a reason to break a working hero.
 * @param {object} r @param {object} s
 */
function remember(r, s) {
  try {
    window.localStorage.setItem(STORE_KEY, s.key + '|' + r.key);
  } catch { /* remembering is a nicety, never a requirement */ }
}

/**
 * Wire the hero picker to the markup already on the page. No-ops on every page but the
 * homepage, and on a homepage whose hero markup has been restructured away.
 */
function initHeroPicker() {
  const stage = document.querySelector('[data-hp-stage]');
  const roomBtn = document.getElementById('hero-room-btn');
  const styleBtn = document.getElementById('hero-style-btn');
  if (!stage || !roomBtn || !styleBtn) return;

  const baseImg = /** @type {HTMLImageElement|null} */ (stage.querySelector('[data-hp-img]'));
  if (!baseImg) return;

  const roomMenu = document.getElementById('hero-room-menu');
  const styleMenu = document.getElementById('hero-style-menu');
  const roomList = document.getElementById('hero-room-list');
  const styleList = document.getElementById('hero-style-list');
  const roomLabel = document.getElementById('hero-room-label');
  const styleLabel = document.getElementById('hero-style-label');
  const originalBtn = document.getElementById('hero-original-btn');
  if (!roomMenu || !styleMenu || !roomList || !styleList || !roomLabel || !styleLabel) return;

  let room = byKey(ROOMS, DEFAULT_ROOM);
  let style = byKey(STYLES, DEFAULT_STYLE);
  let showingOriginal = false;
  let originalImg = null;
  let menusBuilt = false;

  /* The static LCP node is the first entry in the cache, so the default pair is never
     re-fetched and never re-created. Everything else is added on demand. */
  const cache = { [DEFAULT_STYLE + '-' + DEFAULT_ROOM]: baseImg };

  const src = (r, s) => DIR + s.slug + '-' + r.slug + '.webp';
  const pairKey = (r, s) => s.slug + '-' + r.slug;
  /* Alt text takes the PLAIN room name (roomTypes.*), not the sentence form (hero.rooms.*).
     The sentence form carries a demonstrative and, in Russian, accusative case, because it
     has to slot into "Gestalte dieses Schlafzimmer ..." — none of which belongs in a
     description of a photo. */
  const altFor = (r, s) => t('hero.stageAlt')
    .replace('{style}', t(s.label))
    .replace('{room}', t(r.menu));

  /** Every staged render in the stage, i.e. everything except a lazily-added original. */
  const staged = () => Array.prototype.filter.call(
    stage.querySelectorAll('img'),
    (im) => im !== originalImg
  );

  /* ------------------------------------------------------------------ the photo */

  /**
   * Put a pair on screen. The outgoing render stays visible until the incoming one has
   * decoded, so a switch never flashes the empty frame underneath; the spinner sits over
   * the old photo while that happens, which reads as "rendering" rather than as a gap.
   *
   * `initial` marks the one call that is not a switch: restoring a remembered pick during
   * the first paint. That image is the LCP element for a returning visitor, so it asks for
   * high priority, and it shows no spinner — nobody pressed anything, and a spinner over a
   * page that is still arriving reads as broken rather than as busy.
   *
   * @param {object} r @param {object} s @param {boolean} [initial]
   */
  function show(r, s, initial) {
    const key = pairKey(r, s);
    if (cache[key]) {
      staged().forEach((im) => im.classList.toggle('is-on', im === cache[key]));
      stage.classList.remove('is-loading');
      return;
    }
    const img = new Image();
    img.className = 'hp-stage__img';
    img.alt = altFor(r, s);
    img.decoding = 'async';
    if (initial) img.fetchPriority = 'high';
    else stage.classList.add('is-loading');
    img.addEventListener('load', () => {
      stage.classList.remove('is-loading');
      if (pairKey(room, style) !== key || showingOriginal) return; // moved on already
      staged().forEach((im) => im.classList.toggle('is-on', im === img));
    });
    img.addEventListener('error', () => stage.classList.remove('is-loading'));
    img.src = src(r, s);
    stage.appendChild(img);
    cache[key] = img;
  }

  /** Warm the rest of the current room's row, which is where a visitor goes next. */
  function prefetchRow() {
    STYLES.forEach((s) => { if (!cache[pairKey(room, s)]) new Image().src = src(room, s); });
  }

  /* ------------------------------------------------------------------- the menus */

  /**
   * One menu row. The thumbnail is the render that choice would produce, so the range is
   * visible on first open instead of having to be guessed at one pick at a time.
   */
  function rowFor(item, isSelected, thumbSrc, labelKey) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'hp-menu__item';
    btn.setAttribute('role', 'option');
    btn.setAttribute('aria-selected', String(isSelected));
    const thumb = new Image();
    thumb.className = 'hp-menu__thumb';
    thumb.alt = '';
    thumb.loading = 'lazy';
    thumb.decoding = 'async';
    thumb.src = thumbSrc;
    const text = document.createElement('span');
    text.className = 'hp-menu__text';
    text.textContent = t(labelKey);
    btn.append(thumb, text);
    return btn;
  }

  /** Rebuild both menus. Cheap, and the simplest way to stay right across a language change. */
  function buildMenus() {
    roomList.textContent = '';
    styleList.textContent = '';
    ROOMS.forEach((r) => {
      const btn = rowFor(r, r === room, src(r, style), r.menu);
      btn.addEventListener('click', () => { pick('room', r); closeMenus(roomBtn); });
      roomList.appendChild(btn);
    });
    STYLES.forEach((s) => {
      const btn = rowFor(s, s === style, src(room, s), s.label);
      btn.addEventListener('click', () => { pick('style', s); closeMenus(styleBtn); });
      styleList.appendChild(btn);
    });
    menusBuilt = true;
  }

  /** Repaint the two words in the sentence from the current selection. */
  function paintSentence() {
    roomLabel.textContent = t(room.label);
    styleLabel.textContent = t(style.label);
  }

  function pick(which, item) {
    if (which === 'room') room = item; else style = item;
    if (showingOriginal) toggleOriginal(false);
    remember(room, style);
    paintSentence();
    show(room, style);
    buildMenus();
  }

  /* ------------------------------------------------------------ open / close / keys */

  function closeMenus(focusBtn) {
    [[roomBtn, roomMenu], [styleBtn, styleMenu]].forEach(([b, m]) => {
      m.hidden = true;
      b.setAttribute('aria-expanded', 'false');
    });
    if (focusBtn) focusBtn.focus();
  }

  function openMenu(btn, menu) {
    const wasOpen = !menu.hidden;
    closeMenus(null);
    if (wasOpen) return;
    if (!menusBuilt) buildMenus();
    menu.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    const selected = menu.querySelector('[aria-selected="true"]');
    if (selected) /** @type {HTMLElement} */ (selected).focus();
  }

  roomBtn.addEventListener('click', (e) => { e.stopPropagation(); openMenu(roomBtn, roomMenu); });
  styleBtn.addEventListener('click', (e) => { e.stopPropagation(); openMenu(styleBtn, styleMenu); });
  [roomMenu, styleMenu].forEach((m) => m.addEventListener('click', (e) => e.stopPropagation()));
  document.addEventListener('click', () => closeMenus(null));

  document.addEventListener('keydown', (e) => {
    const open = roomMenu.hidden ? (styleMenu.hidden ? null : styleMenu) : roomMenu;
    if (e.key === 'Escape' && open) {
      closeMenus(open === roomMenu ? roomBtn : styleBtn);
      return;
    }
    if (!open || (e.key !== 'ArrowDown' && e.key !== 'ArrowUp')) return;
    e.preventDefault();
    const items = Array.prototype.slice.call(open.querySelectorAll('.hp-menu__item'));
    const at = items.indexOf(/** @type {HTMLElement} */ (document.activeElement));
    const step = e.key === 'ArrowDown' ? 1 : items.length - 1;
    items[(at + step + items.length) % items.length].focus();
  });

  /* -------------------------------------------------------------- see the original */

  /**
   * Show the empty room every render on this page was made from. Loaded on demand rather
   * than up front: it is proof a visitor asks for, not something the first paint owes them.
   * @param {boolean} next
   */
  function toggleOriginal(next) {
    showingOriginal = next;
    if (originalBtn) {
      originalBtn.setAttribute('aria-pressed', String(next));
      originalBtn.textContent = t(next ? 'hero.seeStaged' : 'hero.seeOriginal');
    }
    if (!next) {
      if (originalImg) originalImg.classList.remove('is-on');
      show(room, style);
      return;
    }
    if (!originalImg) {
      originalImg = new Image();
      originalImg.className = 'hp-stage__img';
      originalImg.alt = t('hero.originalAlt');
      originalImg.decoding = 'async';
      originalImg.src = ORIGINAL;
      stage.appendChild(originalImg);
    }
    staged().forEach((im) => im.classList.remove('is-on'));
    originalImg.classList.add('is-on');
  }

  if (originalBtn) {
    originalBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleOriginal(!showingOriginal);
    });
  }

  /* -------------------------------------------------------------------- language */

  window.addEventListener('languagechange', () => {
    paintSentence();
    if (originalBtn) originalBtn.textContent = t(showingOriginal ? 'hero.seeStaged' : 'hero.seeOriginal');
    baseImg.alt = altFor(byKey(ROOMS, DEFAULT_ROOM), byKey(STYLES, DEFAULT_STYLE));
    if (menusBuilt) buildMenus();
  });

  /* ----------------------------------------------------------------------- start */

  /* Hand the three JS-managed strings over from the markup.
   *
   * They ship with `data-lang` so the server-rendered locale pages and the no-JS case are
   * correct, but from here their text depends on what the visitor has picked, and
   * applyTranslations() writes textContent straight from the key. Leave the attributes on
   * and the next language change silently resets the sentence to "bedroom"/"Modern" and the
   * toggle to "See original" while the photo stays where the visitor put it. Dropping the
   * attributes makes the languagechange handler above the only writer. */
  [roomLabel, styleLabel, originalBtn].forEach((el) => el && el.removeAttribute('data-lang'));

  baseImg.classList.add('is-on');
  stage.setAttribute('data-hp-adopted', '');

  /* Restore the last visit's pick, if there was one and it isn't already what the markup
     shipped. This runs before the prefetch below so the row that gets warmed is the row the
     visitor is actually looking at, and it goes through show() like any other change, so the
     default photo stays on screen until the remembered one has decoded.

     On a localized URL the two restored words are written in English for the moment it takes
     the language pack to land, because the pack is fetched in <head> and this runs at the end
     of parsing. The languagechange handler above repaints them. That is the same fallback
     window every other JS-owned string on this page sits in, and it is the better of the two
     trades available: the alternative is holding the sentence at "bedroom"/"Modern" while the
     photo changes underneath it, which reads as a bug rather than as a page still arriving. */
  const stored = readStored();
  if (stored && (stored.room !== room || stored.style !== style)) {
    room = stored.room;
    style = stored.style;
    paintSentence();
    show(room, style, true);
  }

  if ('requestIdleCallback' in window) {
    /** @type {any} */ (window).requestIdleCallback(prefetchRow);
  } else {
    setTimeout(prefetchRow, 1500);
  }
}

/* Called directly rather than on DOMContentLoaded: as the first module tag this runs after
   the parser has passed the hero, and waiting for the event would give the delay back. */
initHeroPicker();
